11.     | undefined
12.     ? "boolean"
13.     : UserPreferences[key] extends string | undefined
14.     ? "string"
15.     : never;
16. } & Record<keyof UserPreferences, string> = {
17.   allowIncompleteCompletions: "boolean",
18.   allowRenameOfImportPath: "boolean",
19.   allowTextChangesInNewFiles: "boolean",
