32.   includeInlayEnumMemberValueHints: "boolean",
33.   includeInlayFunctionLikeReturnTypeHints: "boolean",
34.   includeInlayFunctionParameterTypeHints: "boolean",
35.   includeInlayParameterNameHints: "string",
36.   includeInlayParameterNameHintsWhenArgumentMatchesName: "boolean",
37.   includeInlayPropertyDeclarationTypeHints: "boolean",
38.   includeInlayVariableTypeHints: "boolean",
39.   includePackageJsonAutoImports: "string",
40.   jsxAttributeCompletionStyle: "string",
41.   lazyConfiguredProjectsFromExternalProject: "boolean",
42.   providePrefixAndSuffixTextForRename: "boolean",
43.   provideRefactorNotApplicableReason: "boolean",
44.   quotePreference: "string",
45.   useLabelDetailsInCompletionEntries: "boolean",
46. };
47. 
48. export function setupUserPreferences(): Disposable {
49.   const disposable = new CompositeDisposable();
50.   for (const key in keys) {
51.     const configKey = `apexskier.typescript.config.userPreferences.${key}`;
52.     disposable.add(nova.config.onDidChange(configKey, reload));
53.     disposable.add(nova.workspace.config.onDidChange(configKey, reload));
54.   }
55.   return disposable;
56. }
